commands.windows:
# Standalone example: Hashes one explicitly selected file. Edit the path to change the watched file. Custom results do not enter the built-in integrity baseline, diff, or alert pipeline.
$ErrorActionPreference = "Stop"
Get-FileHash -Algorithm SHA256 "$env:SystemRoot\System32\drivers\etc\hosts" | ForEach-Object { '{0} {1}' -f $_.Hash, $_.Path }
